#include <bits/stdc++.h>
using namespace std;

const int maxn = 510;

int m, n, mod;

inline int add (int x, int y) {return (1LL * x + y) % mod;}
inline int sub (int x, int y) {return x - y < 0 ? x - y + mod : x - y;}
inline int mul (int x, int y) {return 1LL * x * y % mod;}
int fac[maxn], inv[maxn], invfac[maxn];
void get_fac_and_inv(int n)
{
    fac[0] = inv[1] = fac[1] = invfac[0] = invfac[1] = 1LL;
    for (int i = 2; i <= n; i++) inv[i] = mul((mod - mod / i), inv[mod % i]);
    for (int i = 2; i <= n; i++) {fac[i] = mul (fac[i - 1], i); invfac[i] = mul (invfac[i - 1], inv[i]);}
}
inline int C (int n, int m) {if (n < m || m < 0) return 0; return mul(mul(fac[n], invfac[m]), invfac[n - m]);}
inline int P (int n, int m) {return C(n + m - 1, m - 1);}


int f[maxn], g[maxn], s[maxn];
int ff[maxn][maxn], gg[maxn][maxn];

int main()
{
    scanf ("%d %d %d", &n, &m, &mod);
    get_fac_and_inv (500);
    for (int i = 1; i <= n; i++) s[i] = add (s[i - 1], i);
    f[0] = 1; f[1] = 2;
    g[0] = 0; g[1] = 0;
    for (int i = 2; i <= n; i++)
    {
        for (int j = 0; j < i; j++)
        {
            int temp = mul (C (i - 1, j), mul(f[j], f[i - 1 - j]));
            f[i] = add (f[i], mul (temp, i + 1));
            g[i] = add (g[i], mul (temp, s[j] + s[i - 1 - j]));
            temp = mul (add (mul (g[j], f[i - 1 - j]), mul (g[i - 1 - j], f[j])), i + 1);
            g[i] = add (g[i], mul (temp, C(i - 1, j)));
        }
    }
    ff[0][0] = 1; gg[0][0] = 0;
    for (int i = 0; i <= m; i++)
        for (int j = 0; j <= m; j++)
        {
            if (!ff[i][j]) continue;
            for (int k = 1; k + j <= m; k++)
            {
                ff[i + 1][j + k] = add (ff[i + 1][j + k], mul (mul (ff[i][j], f[k]), C(j + k, k)));
                gg[i + 1][j + k] = add (gg[i + 1][j + k], mul (add (mul (gg[i][j], f[k]), mul (ff[i][j], g[k])), C(j + k, k)));
            }
        }
    int ans = 0;
    for (int i = 1; i <= m; i++)
        if (n + 1 - m >= i)
            ans = add (ans, mul (gg[i][m], P (n + 1 - m - i, i + 1)));
    printf ("%d\n", ans);
    return 0;
}

